import os
import re

def load_grids():
    try:
        d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
        fname = os.path.basename(d) + '.jsonl'
        with open(d+'/../../sessions/'+fname) as f:
            content = f.read()
    except Exception as e:
        print(f"Error loading: {e}")
        return {}

    print(f"Loaded content length: {len(content)}")
    print(f"First 500 chars: {content[:500]}")

    G = {}
    pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n'
    matches = list(re.finditer(pattern, content))
    print(f"Found {len(matches)} matches")

    for i, m in enumerate(matches):
        k, h, w = m[1], m[2], m[3]
        h, w = int(h), int(w)
        start = m.end()
        # Find the end - next grid marker or end of file
        remaining = content[start:]
        next_match = re.search(pattern, remaining)
        if next_match:
            end = start + next_match.start()
        else:
            end = len(content)

        grid_str = content[start:end].strip()
        rows = grid_str.split('\n')
        print(f"\n{m[1]} at pos {start}: {len(rows)} rows found")
        for idx, row in enumerate(rows):
            parts = row.split()
            if parts:
                try:
                    vals = [int(x) for x in parts]
                    print(f"  Row {idx}: len={len(vals)}, sample={vals[:5]}...")
                except:
                    print(f"  Row {idx}: non-numeric: {row[:50]}...")

    return G

grids = load_grids()

